1	// HARU가계부 — 카카오뱅크 거래내역 XLSX(암호 해제 후) 파싱·매핑·월별 그룹핑
2	// 잠금 해제는 Functions(decryptKakaoXlsx)에서 처리하고, 이 파일은 순수 파싱/매핑만 담당한다.
3	// 기존 거래 필드는 보존하고 재가져오기 식별용 해시·원본 거래 시각을 함께 채운다.
4	import type { HouseholdEntry } from '../components/FormatModal';
5	import { householdDigest } from './householdDuplicates';
6	
7	export interface KakaoXlsxPreviewRow {
8	  id: string;
9	  selected: boolean;
10	  warning: string;
11	  entry: HouseholdEntry;
12	}
13	
14	export interface KakaoXlsxParseResult {
15	  rows: KakaoXlsxPreviewRow[];
16	  scannedRowCount: number;
17	}
18	
19	export interface KakaoXlsxMonthGroup {
20	  month: string; // 'YYYY-MM'
21	  rows: KakaoXlsxPreviewRow[];
22	}
23	
24	interface SheetJsLike {
25	  utils: {
26	    sheet_to_json<T>(sheet: unknown, options: Record<string, unknown>): T[];
27	  };
28	}
29	
30	interface WorkbookLike {
31	  SheetNames: string[];
32	  Sheets: Record<string, unknown>;
33	}
34	
35	// 지출 vendor에 아래 키워드가 포함되면 '구독료'로 분류 (소문자 비교)
36	const SUBSCRIPTION_KEYWORDS = [
37	  'anthropic', 'claude', 'google', '구글', 'openai', 'chatgpt', 'microsoft', 'netflix', '구독', '유튜브', 'youtube',
38	];
39	
40	function parseKakaoDate(raw: unknown): string {
41	  const m = String(raw ?? '').trim().match(/^(\d{4})\.(\d{2})\.(\d{2})/);
42	  return m ? `${m[1]}-${m[2]}-${m[3]}` : '';
43	}
44	
45	function parseKakaoAmount(raw: unknown): string {
46	  const n = parseFloat(String(raw ?? '').replace(/[^0-9.-]/g, ''));
47	  if (!Number.isFinite(n) || n === 0) return '';
48	  return String(Math.abs(n));
49	}
50	
51	// 거래후잔액(E열) — 콤마 제거 후 숫자 문자열로. 비어있으면 undefined(손입력 기록과 동일하게 필드 자체를 생략).
52	function parseKakaoBalanceAfter(raw: unknown): string | undefined {
53	  const trimmed = String(raw ?? '').replace(/,/g, '').trim();
54	  return trimmed === '' ? undefined : trimmed;
55	}
56	
57	function normalizeVendor(raw: unknown): string {
58	  return String(raw ?? '').replace(/\s+/g, ' ').trim();
59	}
60	
61	// 파일 상단 메타영역에서 '성명' 라벨 오른쪽 셀 값을 본인 계좌 명의로 추출한다.
62	// 거래 데이터 행(유효 날짜)이 시작되면 탐색을 멈춘다. 못 찾으면 '' 반환(호출부에서 안전하게 폴백).
63	function findAccountHolderName(rawRows: unknown[][]): string {
64	  for (const rawRow of rawRows) {
65	    const cells = Array.isArray(rawRow) ? rawRow : [];
66	    if (parseKakaoDate(cells[1])) break; // 메타영역 종료 — 거래 데이터 시작
67	    for (let i = 0; i < cells.length - 1; i++) {
68	      if (String(cells[i] ?? '').trim() === '성명') {
69	        const name = normalizeVendor(cells[i + 1]);
70	        if (name) return name;
71	      }
72	    }
73	  }
74	  return '';
75	}
76	
77	// 구분==='입금'이면서 내용(vendor)이 본인 성명과 일치하면 본인 계좌간 이체(충전)로 분류한다.
78	// accountHolderName을 못 찾은 경우(빈 문자열)에는 기존 동작(입금→수입)을 그대로 유지한다.
79	function mapTransactionType(
80	  raw: unknown,
81	  vendorRaw: unknown,
82	  accountHolderName: string,
83	): { type: HouseholdEntry['transactionType']; recognized: boolean } {
84	  const v = String(raw ?? '').trim();
85	  if (v === '입금') {
86	    if (accountHolderName && normalizeVendor(vendorRaw) === accountHolderName) {
87	      return { type: '이체', recognized: true };
88	    }
89	    return { type: '수입', recognized: true };
90	  }
91	  if (v === '출금') return { type: '지출', recognized: true };
92	  return { type: '지출', recognized: false };
93	}
94	
95	function mapPaymentMethod(raw: unknown): string {
96	  const v = String(raw ?? '').trim();
97	  if (v === '체크카드결제') return '체크카드';
98	  if (v === '카드출금') return '현금';
99	  if (v === '예금이자' || v === '캐시백') return '기타';
100	  if (v === '일반이체' || v === '일반입금' || v.startsWith('자동이체')) return '계좌이체';
101	  return '기타';
102	}
103	
104	// 은행 미리보기에서 구분·거래처를 고칠 때도 같은 파서 기본값을 다시 쓴다.
105	export function mapCategory(transactionType: HouseholdEntry['transactionType'], vendor: string): string {
106	  if (transactionType === '수입') return '기타수입';
107	  if (transactionType === '이체') return '이체'; // FormatModal 수동입력의 이체 카테고리 규칙과 동일
108	  const v = vendor.toLowerCase();
109	  return SUBSCRIPTION_KEYWORDS.some((k) => v.includes(k)) ? '구독료' : '기타';
110	}
111	
112	// 해제된 워크북의 첫 번째 시트를 카카오뱅크 거래내역 형식으로 파싱한다.
113	// 열(0-index, A열은 비어있음): [1]거래일시 [2]구분 [3]거래금액 [4]거래후잔액 [5]거래구분 [6]내용 [7]메모
114	// 유효 거래 판별: [1]거래일시가 'YYYY.MM.DD ...' 형식인 행만 취급 (메타정보/헤더 행은 자동 제외됨)
115	// 본인이체 판별: 구분==='입금' && 내용===메타영역 '성명' 값이면 '이체'로 분류(본인 계좌간 충전, 수입 아님)
116	export async function parseKakaoBankWorkbook(
117	  workbook: WorkbookLike,
118	  XLSX: SheetJsLike,
119	  sourceFileName: string,
120	): Promise<KakaoXlsxParseResult> {
121	  const rows: KakaoXlsxPreviewRow[] = [];
122	  const sheetName = workbook.SheetNames[0];
123	  if (!sheetName) return { rows, scannedRowCount: 0 };
124	
125	  const sheet = workbook.Sheets[sheetName];
126	  const rawRows = XLSX.utils.sheet_to_json<unknown[]>(sheet, { header: 1, defval: '' });
127	  const accountHolderName = findAccountHolderName(rawRows);
128	  // 파일명·암호와 무관한 복호화 자료의 해시. 메타영역 원문은 저장하지 않는다.
129	  const fileDigest = await householdDigest(rawRows.map(row => row.map(cell => String(cell ?? '').normalize('NFKC').trim())));
130	
131	  for (const [sourceRow, rawRow] of rawRows.entries()) {
132	    const cells = Array.isArray(rawRow) ? rawRow : [];
133	    const date = parseKakaoDate(cells[1]);
134	    if (!date) continue; // 메타정보/헤더/빈 행 — 유효 거래 아님
135	
136	    const { type: transactionType, recognized } = mapTransactionType(cells[2], cells[6], accountHolderName);
137	    const amount = parseKakaoAmount(cells[3]);
138	    const balanceAfter = parseKakaoBalanceAfter(cells[4]);
139	    const vendor = normalizeVendor(cells[6]);
140	    const paymentMethod = mapPaymentMethod(cells[5]);
141	    const category = mapCategory(transactionType, vendor);
142	    const key = `kakao:${await householdDigest([fileDigest, sourceRow])}`;
143	
144	    const warnings: string[] = [];
145	    if (!recognized) warnings.push(`구분 값을 확인해 주세요("${String(cells[2] ?? '').trim()}")`);
146	    if (!amount) warnings.push('금액을 확인해 주세요');
147	    if (transactionType === '지출' && !vendor) warnings.push('사용처를 확인해 주세요');
148	
149	    const entry: HouseholdEntry = {
150	      id: key,
151	      transactionType,
152	      category,
153	      // 파서가 정한 분류는 사용자가 고른 값과 구분한다. 거래처 기억은 이 값 위에만 제안한다.
154	      categorySource: 'import-default',
155	      date,
156	      vendor,
157	      amount,
158	      paymentMethod,
159	      memo: '',
160	      ocrSourceFile: sourceFileName,
161	      balanceAfter,
162	      transactionAt: String(cells[1] ?? '').trim().replace(/\./g, '-'),
163	      importSource: { kind: 'kakao', fileDigest, key },
164	    };
165	
166	    rows.push({
167	      id: entry.id,
168	      selected: true,
169	      warning: warnings.join(' · '),
170	      entry,
171	    });
172	  }
173	
174	  return { rows, scannedRowCount: rawRows.length };
175	}
176	
177	// entry.date('YYYY-MM-DD') 기준 'YYYY-MM'으로 그룹핑, 월 오름차순 정렬
178	export function groupKakaoRowsByMonth(rows: KakaoXlsxPreviewRow[]): KakaoXlsxMonthGroup[] {
179	  const map = new Map<string, KakaoXlsxPreviewRow[]>();
180	  for (const row of rows) {
181	    const month = row.entry.date.slice(0, 7);
