1	import { collection, doc, getDocsFromServer, runTransaction, type Firestore } from 'firebase/firestore';
2	import type { HouseholdEntry } from '../components/FormatModal';
3	import { parseHouseholdAmountText } from '../utils/householdAmount';
4	import { checkHouseholdDuplicates, householdDate, householdIdentity, householdStoredEntries,
5	  HouseholdDuplicateReviewRequired, type HouseholdDecisions, type HouseholdStoredRecord } from './householdDuplicates';
6	
7	export interface HouseholdSaveResult {
8	  kind: 'household'; added: number; skipped: number; already: number; recordIds: string[]; createdRecords: number;
9	}
10	
11	export class HouseholdOriginalConflict extends Error {
12	  constructor() {
13	    super('다른 곳에서 가계부가 바뀌었습니다. 창을 닫고 다시 열어 확인해 주세요. 저장하지 않았습니다.');
14	    this.name = 'HouseholdOriginalConflict';
15	  }
16	}
17	
18	export async function loadHouseholdRecords(db: Firestore, uid: string): Promise<HouseholdStoredRecord[]> {
19	  if (!uid || uid.includes('/')) throw new Error('로그인이 필요합니다.');
20	  // 캐시/오프라인의 빈 결과로 중복 검사를 우회하지 않는다.
21	  const snapshot = await getDocsFromServer(collection(db, 'users', uid, 'records'));
22	  return snapshot.docs.map(item => ({ id: item.id, data: item.data() }))
23	    .filter(item => Object.keys(item.data).some(key => key.startsWith('household_')));
24	}
25	
26	export function householdMonthRecordId(date: string) { return `${householdDate(date).slice(0, 7)}-01_household`; }
27	
28	// 원본 편집은 바꾼 필드만 저장한다. 열어 둔 사이 추가된 거래를 낡은 배열로 덮어쓰지 않는다.
29	export async function saveHouseholdOriginal(db: Firestore, uid: string, recordId: string,
30	  opened: Record<string, string>, edited: Record<string, string>) {
31	  const changed = Object.fromEntries(Object.entries(edited).filter(([key, value]) => value !== opened[key]));
32	  if (!Object.keys(changed).length) return;
33	  const ref = doc(db, 'users', uid, 'records', recordId);
34	  await runTransaction(db, async transaction => {
35	    const current = await transaction.get(ref);
36	    if (!current.exists() || current.data().household_entries !== opened.household_entries
37	      || Object.keys(changed).some(key => current.data()?.[key] !== opened[key])) {
38	      throw new HouseholdOriginalConflict();
39	    }
40	    transaction.update(ref, changed);
41	  });
42	}
43	
44	// 저장 서비스가 자동으로 만드는 기록 본문. 거래 편집은 본문이 이 결과와 같을 때만 다시 만든다.
45	export function householdSayuText(entries: HouseholdEntry[]) {
46	  return entries.map(entry => `[${entry.transactionType}] ${entry.date} ${entry.amount}원 ${entry.vendor}${entry.memo ? '\n메모: ' + entry.memo : ''}`).join('\n\n');
47	}
48	
49	function fields(entries: HouseholdEntry[]) {
50	  const first = entries[0];
51	  return {
52	    household_entries: JSON.stringify(entries), household_type: first.transactionType,
53	    household_category: first.category, household_date: first.date, household_vendor: first.vendor,
54	    household_amount: first.amount, household_payment: first.paymentMethod, household_memo: first.memo,
55	    household_sayu: householdSayuText(entries),
56	  };
57	}
58	
59	export async function saveHouseholdEntries(db: Firestore, uid: string, entries: HouseholdEntry[], decisions: HouseholdDecisions = {}): Promise<HouseholdSaveResult> {
60	  if (!uid || uid.includes('/')) throw new Error('로그인이 필요합니다.');
61	  if (!entries.length) throw new Error('저장할 거래가 없습니다.');
62	  const ids = new Set<string>();
63	  for (const entry of entries) {
64	    householdDate(entry.date);
65	    if (!entry.id || ids.has(entry.id) || !['수입','지출','이체'].includes(entry.transactionType)
66	      || parseHouseholdAmountText(entry.amount) === null || (entry.transactionType === '지출' && !entry.vendor.trim())) {
67	      throw new Error('날짜·거래종류·금액·사용처를 확인해 주세요.');
68	    }
69	    ids.add(entry.id);
70	  }
71	  const loaded = await loadHouseholdRecords(db, uid);
72	  const initialChecks = await checkHouseholdDuplicates(entries, loaded);
73	  const targetIds = [...new Set(entries.map(entry => householdMonthRecordId(entry.date)))];
74	  // 같은 거래 월의 신규 저장은 항상 동일 문서를 읽고 써서 기기 간 충돌도 재검증한다.
75	  // 기존 문서는 이동하지 않는다. 관련된 기존 거래만 트랜잭션 안에서 다시 읽는다.
76	  const readIds = [...new Set([...targetIds, ...initialChecks.flatMap(check => check.matches.map(match => match.recordId)).filter(Boolean),
77	    ...loaded.filter(record => record.data.household_importKeys?.some((key: string) => entries.some(entry => householdIdentity(entry) === key))).map(record => record.id)])];
78	  if (readIds.length > 400) throw new Error('한 번에 확인할 기록이 많습니다. 가져올 기간을 줄여 주세요.');
79	  return runTransaction(db, async transaction => {
80	    const snapshots = await Promise.all(readIds.map(id => transaction.get(doc(db, 'users', uid, 'records', id))));
81	    const records = snapshots.filter(snapshot => snapshot.exists()).map(snapshot => ({ id: snapshot.id, data: snapshot.data()! }));
82	    const analyzed = await checkHouseholdDuplicates(entries, records);
83	    // 이전에 사용자가 비교했던 거래가 사라지거나 금액이 바뀌어도
84	    // 그 선택을 무시하고 신규 거래로 자동 추가하지 않는다.
85	    const checks = analyzed.map(check => check.status === 'new' && decisions[check.entry.id]
86	      ? { ...check, status: 'suspect' as const } : check);
87	    if (checks.some(check => check.status === 'suspect' && (decisions[check.entry.id]?.token !== check.token
88	      || !['skip', 'keep'].includes(decisions[check.entry.id]?.action)
89	      || (decisions[check.entry.id]?.action === 'skip' && !check.matches.length)))) {
90	      throw new HouseholdDuplicateReviewRequired(checks);
91	    }
92	    const additions = new Map<string, HouseholdEntry[]>();
93	    const receipts = new Map<string, string[]>();
94	    let already = 0, skipped = 0, added = 0, createdRecords = 0;
95	    for (const check of checks) {
96	      if (check.status === 'already') { already++; continue; }
97	      if (check.status === 'suspect' && decisions[check.entry.id]?.action === 'skip') {
98	        skipped++;
99	        const match = check.matches.find(item => item.recordId)
100	          || check.matches.find(item => additions.get(householdMonthRecordId(item.entry.date))?.some(entry => entry.id === item.entryId));
101	        if (match) {
102	          const recordId = match.recordId || householdMonthRecordId(match.entry.date);
103	          receipts.set(recordId, [...(receipts.get(recordId) || []), householdIdentity(check.entry)]);
104	        }
105	        continue;
106	      }
107	      const target = householdMonthRecordId(check.entry.date);
108	      additions.set(target, [...(additions.get(target) || []), check.entry]);
109	      added++;
110	    }
111	    const touched = new Set([...additions.keys(), ...receipts.keys()]);
112	    for (const id of touched) {
113	      const old = records.find(record => record.id === id);
114	      const next = additions.has(id) ? [...(old ? householdStoredEntries(old) : []), ...additions.get(id)!] : [];
115	      const patch: Record<string, any> = {};
116	      if (next.length) {
117	        Object.assign(patch, { household_entries: JSON.stringify(next), updatedAt: new Date().toISOString() });
118	        if (old?.data.household_sayu) {
119	          patch.household_sayu = old.data.household_sayu + '\n\n' + fields(additions.get(id)!).household_sayu;
120	        } else patch.household_sayu = fields(next).household_sayu;
121	        if (!old || !Object.keys(old.data).some(key => key.startsWith('household_'))) {
122	          Object.assign(patch, fields(next), { household_style: 'premium', household_mode: 'ORIGINAL', household_title: `${id.slice(0,7)} 가계부` });
123	        }
124	        patch.formats = [...new Set([...(Array.isArray(old?.data.formats) ? old.data.formats : []), 'HARU가계부'])];
125	        if (!old) {
126	          createdRecords++;
127	          Object.assign(patch, { date: id.slice(0,10), createdAt: new Date().toISOString() });
128	        }
129	      }
130	      if (receipts.has(id)) patch.household_importKeys = [...new Set([...(old?.data.household_importKeys || []), ...receipts.get(id)!])];
131	      transaction.set(doc(db, 'users', uid, 'records', id), patch, { merge: true });
132	    }
133	    return { kind: 'household', added, skipped, already, recordIds: [...touched], createdRecords };
134	  });
135	}
