  householdEntryMode?: 'bank';
  onSave: (formatData: Record<string, string>) => Promise<string | void | HouseholdSaveResult>;
}

interface PolishResult {
  text: string;
}

type MonthlyAiQuotaStatus = {
  plan: 'free' | 'basic' | 'premium' | 'developer';
  used: number;
  limit: number;
  remaining: number;
  period: string;
  freeLimit: number;
  basicLimit: number;
  premiumLimit: number;
  developerLimit?: number;
};

interface BookOcrResult {
  text?: string;
  usedCount?: number | null;
  limit?: number | null;
  remainingCount?: number | null;
  isDeveloper?: boolean;
}

interface StockOcrResult {
  text?: string;
  trade?: Partial<{
    stock_type: string;
    stock_name: string;
    stock_price: string;
    stock_quantity: string;
    stock_total: string;
    stock_date: string;
  }>;
}

interface LedgerOcrFields {
  transactionAt?: string | null;
  type?: string | null;
  category?: string | null;
  partner?: string | null;
  amount?: string | number | null;
  paymentMethod?: string | null;
  proofType?: string | null;
  memo?: string | null;
}

interface LedgerOcrResult {
  rawText?: string;
  transactions?: LedgerOcrFields[];
  fields?: LedgerOcrFields;
  warnings?: string[];
}


// ===== HARU가계부 =====
const HOUSEHOLD_CATEGORIES = ['식비', '교통비', '통신비', '주거비', '공과금', '의료비', '교육비', '문화생활', '쇼핑', '구독료', '기타'] as const;
const INCOME_CATEGORIES = ['월급', '부수입', '용돈', '환급', '투자수익', '기타수입'] as const;
const HOUSEHOLD_PAYMENT_METHODS = ['현금', '체크카드', '신용카드', '계좌이체', '카카오페이', '네이버페이', '기타'] as const;

export interface HouseholdEntry {
  id: string;
  transactionType: '수입' | '지출' | '이체';
  category: string;
  date: string;
  vendor: string;
  amount: string;
  paymentMethod: string;
  memo: string;
  ocrSourceFile?: string;
  balanceAfter?: string; // 거래 후 잔액(카카오뱅크 임포트 전용) — 손입력 기록엔 없음
  transactionAt?: string;
  importSource?: { kind: 'kakao'; fileDigest: string; key: string };
  subcategory?: string;
  // 새로 저장·수정한 거래에만 붙는다. 기존 거래에는 쓰지 않는다.
  categorySource?: 'user' | 'rule' | 'import-default';
}

function newHouseholdEntry(overrides?: Partial<HouseholdEntry>): HouseholdEntry {
  return {
    id: Array.from(crypto.getRandomValues(new Uint8Array(16)), value => value.toString(16).padStart(2, '0')).join(''),
    transactionType: '지출',
    category: '',
    date: '',
    vendor: '',
    amount: '',
    paymentMethod: '',
    memo: '',
    ...overrides,
  };
}

